using System;using System.Globalization;using System.Linq;using ForteMove.Models.Operations;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Admin.Operations{public partial class DefectDetails:AdminPage{private long Id{get{long x;return long.TryParse(Request.QueryString["id"],out x)?x:0;}}protected void Page_Load(object s,EventArgs e){if(!IsPostBack)Bind();}private void Bind(){var d=ServiceFactory.CreateOperationsAdminService().GetDefectDetails(Id);if(d==null){Response.Redirect(ResolveUrl("~/Admin/Operations/Defects.aspx"),true);return;}lnkMaintenance.NavigateUrl="~/Admin/Maintenance/CreateWorkOrder.aspx?busId="+d.BusId+"&defectId="+d.BusDefectReportId;lnkMaintenance.Visible=d.Status!=DefectStatus.Resolved;litCode.Text=Server.HtmlEncode(d.DefectCode);litBus.Text=Server.HtmlEncode(d.FleetNumber);litSeverity.Text=Server.HtmlEncode(d.Severity.ToString());litCategory.Text=Server.HtmlEncode(FormatCategory(d.Category.ToString()));litStatus.Text=Server.HtmlEncode(d.Status.ToString());litTrip.Text=Server.HtmlEncode(d.TripCode??"Not linked");litDescription.Text=Server.HtmlEncode(d.Description);litDriver.Text=Server.HtmlEncode(d.EmployeeNumber+" · "+d.DriverName);litReported.Text=ServiceFactory.CreateOperationsAdminService().ToOperationalTime(d.ReportedUtc).ToString("dd MMM yyyy HH:mm",CultureInfo.CurrentCulture);hidRv.Value=Convert.ToBase64String(d.RowVersion);btnReview.Visible=d.Status==DefectStatus.Open;btnResolve.Visible=d.Status!=DefectStatus.Resolved;pnlActions.Visible=d.Status!=DefectStatus.Resolved;pnlPrevious.Visible=!string.IsNullOrWhiteSpace(d.ReviewNote)||!string.IsNullOrWhiteSpace(d.ResolutionNote);litPrevious.Text=Server.HtmlEncode(!string.IsNullOrWhiteSpace(d.ResolutionNote)?"Resolution: "+d.ResolutionNote:"Review: "+d.ReviewNote);}protected void btnReview_Click(object s,EventArgs e){Run(ServiceFactory.CreateOperationsAdminService().ReviewDefect(RequestModel(),CurrentPrincipalContext.UserAccountId),"Defect marked reviewed.");}protected void btnResolve_Click(object s,EventArgs e){Run(ServiceFactory.CreateOperationsAdminService().ResolveDefect(RequestModel(),CurrentPrincipalContext.UserAccountId),"Defect resolved.");}private UpdateDefectRequest RequestModel(){return new UpdateDefectRequest{BusDefectReportId=Id,Note=txtNote.Text,RowVersion=Parse(hidRv.Value)};}private void Run(ForteMove.Models.Common.ServiceResult<bool> r,string success){pnlMessage.CssClass=r.Succeeded?"alert alert-success":"alert alert-danger";litMessage.Text=Server.HtmlEncode(r.Succeeded?success:string.Join(" ",r.Errors.Select(x=>x.Message)));pnlMessage.Visible=true;Bind();}private static string FormatCategory(string x){return x=="EngineDrivetrain"?"Engine / drivetrain":x=="BodyInterior"?"Body / interior":x;}private static byte[] Parse(string x){try{return Convert.FromBase64String(x);}catch{return null;}}}}
